            ',
        ],

        'circular-economy-heavy-vehicles' => [
            'title'   => 'الاقتصاد الدائري في المركبات الثقيلة: التفكيك وإعادة التصنيع والاسترداد',
            'excerpt' => 'نموذج الاستخدام ثم الرمي يقترب من نهاية صلاحيته في المركبات الثقيلة أيضًا: المركبات القابلة للتفكيك وإعادة التصنيع والاسترداد تخدم البيئة والميزانية معًا.',
            'content' => '
                <p>النموذج الخطي الكلاسيكي كان بسيطًا: أنتِج، استخدِم، حوِّل إلى خردة. الاقتصاد الدائري يُغلِق هذه السلسلة: المركبة التي تُنهي عمرها الاقتصادي تُفكَّك، وتُدخَل مكوّناتها القيّمة في إعادة التصنيع، وتُسترَد موادها، وتبدأ الدورة من جديد. المركبة الثقيلة التي تحمل أطنانًا من الفولاذ والألمنيوم ومكوّنات نوعية هي واحدة من أكثر مجالات تطبيق هذا النموذج كفاءة.</p>
                <h2>الحلقات الثلاث: التفكيك، إعادة التصنيع، الاسترداد</h2>
                <p>التفكيك المنهجي يتعامل مع المركبة لا ككومة خردة بل كمكتبة مكوّنات: تُفصَل المحاور ومكوّنات الفرامل وعناصر التعليق وتُصنَّف وفق حالتها. تُعيد إعادة التصنيع (remanufacturing) المكوّنات المناسبة إلى ضبط المصنع الأصلي. أما الكتلة المتبقية فتُسترَد على أساس المادة؛ ويتحول الفولاذ والألمنيوم إلى منتجات جديدة دون فقدان خصائصهما. تُظهر الدراسات الأكاديمية حول القطاع أن هذه السلسلة تُنتِج عائدًا اقتصاديًا مباشرًا لا بيئيًا فقط.</p>
                <h2>الدرس العائد إلى طاولة التصميم</h2>
                <ul>
                    <li>تُفضَّل الوصلات المُبرغَمة والمعيارية على البنى المُلصَقة والمختلطة</li>
                    <li>يُخفَّض تنوع المواد؛ فالوحدات ذات المادة الواحدة تُسهِّل الفصل</li>
                    <li>بيانات هوية المكوّنات وتاريخها هي أساس قرار الحياة الثانية</li>
                    <li>دليل التفكيك أصبح الآن جزءًا من توثيق المنتج</li>
                </ul>
                <p>المركبة القابلة للتفكيك هي المركبة التي تحافظ على قيمتها؛ والتصميم الدائري ليس تكلفة بل استثمارًا في قيمة نهاية عمر المركبة.</p>
                <h2>المصادر</h2>
                <ul>
                    <li>Saidani, M., Yannou, B., Leroy, Y. &amp; Cluzel, F. (2020). Dismantling, remanufacturing and recovering heavy vehicles in a circular economy. <em>Resources, Conservation and Recycling</em>, 156, 104684. DOI: 10.1016/j.resconrec.2020.104684</li>
                </ul>
            ',
        ],

        'trailer-remanufacturing' => [
            'title'   => 'إعادة التصنيع في المقطورات: اقتصاد الحياة الثانية',
            'excerpt' => 'إعادة التصنيع تنقل المقطورات المستعملة إلى ما هو أبعد من الإصلاح: المركبة والمكوّنات التي تعود إلى معيار المصنع تكتسب عمرًا اقتصاديًا ثانيًا.',
            'content' => '
                <p>الإصلاح يُعيد القطعة المعطوبة إلى العمل؛ والتجديد يُنعِش مظهر المركبة. أما إعادة التصنيع (remanufacturing) فهي أكثر من الاثنين معًا: تُفكَّك المركبة أو المكوّن بالكامل في بيئة المصنع، وتُقاس كل قطعة، وتُستبدَل القطع المتآكلة، ويُعاد تجميع المنتج واختباره وفق معيار محدَّد. النتيجة ليست سوقًا ثانويًا؛ بل بداية حياة ثانية.</p>
                <h2>لماذا المقطورة مرشَّح مثالي؟</h2>
                <p>البنية الأساسية للمقطورة — الشاسيه، وصلات المحاور، هيكل الجسم — مصمَّمة بمتانة تتجاوز عمر الاستخدام الأول عند الصيانة الصحيحة. الجانب الأكثر تآكلًا غالبًا هو الوحدات المحيطة: الفرامل، عناصر التعليق، التمديدات الكهربائية، الأرضية والأبواب. تُظهر الدراسات الأكاديمية التي تفحص قطاع المركبات الثقيلة أن هذه البنية مناسبة تمامًا لاقتصاد التفكيك وإعادة التصنيع: نواة عالية القيمة وطويلة العمر؛ ومكوّنات محيطة قابلة للاستبدال وموحَّدة قياسيًا.</p>
                <h2>اقتصاد الحياة الثانية</h2>
                <ul>
                    <li>المركبة المُعاد تصنيعها تنضم إلى الأسطول بتكلفة أقل بشكل ملحوظ من المركبة الجديدة</li>
                    <li>الشاسيه والجسم اللذان دُفِع كربونهما المتضمَّن مسبقًا يدخلان في حساب الانبعاث بخفة في عمرهما الثاني</li>
                    <li>عندما تُوثَّق عملية إعادة التصنيع بالاختبار والضمان، يزول عدم يقين السوق الثانوية</li>
                    <li>بما أنها تعتمد على العمالة المحلية بشكل كبير، فإنها تغذّي التوظيف وشبكة الخدمة</li>
                </ul>
                <p>في استراتيجية الأسطول، إعادة التصنيع ليست بديلًا عن الاستثمار الجديد بل مكمّلة له: مركبة جديدة للخطوط الكثيفة، ومركبة مُعاد تصنيعها للأعمال القابلة للتنبؤ — هذا بالضبط هو التوزيع الكفؤ لرأس المال.</p>
                <h2>المصادر</h2>
                <ul>
                    <li>Saidani, M., Yannou, B., Leroy, Y. &amp; Cluzel, F. (2020). Dismantling, remanufacturing and recovering heavy vehicles in a circular economy. <em>Resources, Conservation and Recycling</em>, 156, 104684. DOI: 10.1016/j.resconrec.2020.104684</li>
                </ul>
            ',
        ],

        'trailer-lifecycle-assessment' => [
            'title'   => 'تحليل دورة الحياة: البصمة الكربونية الحقيقية للمقطورة',
            'excerpt' => 'قصة المقطورة الكربونية تبدأ في المصنع لكنها لا تنتهي هناك؛ البصمة الحقيقية هي مجموع الدورة الكاملة الممتدة من المادة الخام إلى الخردة.',
            'content' => '
                <p>غالبًا ما يتركّز نقاش الكربون على أنبوب العادم؛ في حين أن المقطورة نفسها لا تحرق وقودًا. لرؤية قصتها الكربونية، يلزم تحليل دورة الحياة (LCA): منهج منهجي يُدرِج انبعاثات جميع المراحل — من إنتاج المادة الخام إلى التصنيع، ومن عمر الاستخدام إلى نهاية العمر — في الحساب نفسه.</p>
                <h2>مراحل الدورة</h2>
                <ul>
                    <li><strong>المادة الخام:</strong> الكثافة الكربونية لإنتاج الفولاذ والألمنيوم؛ والمدخل المُعاد تدويره يُخفّض هذا البند بشكل ملحوظ</li>
                    <li><strong>التصنيع:</strong> استهلاك الطاقة في القص واللحام والطلاء والتجميع</li>
                    <li><strong>الاستخدام:</strong> حصة وزن المقطورة وديناميكيتها الهوائية المنعكسة على استهلاك وقود الجرار</li>
                    <li><strong>نهاية العمر:</strong> الأثر الصافي للتفكيك والاسترداد والتخلص</li>
                </ul>
                <h2>الكفّة الأثقل في الميزان: مرحلة الاستخدام</h2>
                <p>على مدى عمر يمتد لمئات آلاف الكيلومترات، يشارك وزن المقطورة ومقاومتها الهوائية في كل لتر يحرقه الجرار؛ لذا فإن مرحلة الاستخدام هي البند الأكبر بفارق كبير في إجمالي البصمة. هذه الحقيقة تؤثر مباشرة على قرارات التصميم: تحمّل بعض الانبعاث الإضافي في الإنتاج مقابل التخفيف من الوزن يُعوَّض بسرعة وبأكثر من قيمته عبر المكسب في مرحلة الاستخدام. المنطق نفسه ينطبق على المتانة: المركبة التي يطول عمرها تُقسِّم كربونها المتضمَّن على عدد أكبر من الكيلومترات.</p>
                <p>تحليل دورة الحياة ليس ملصق تسويق بل أداة قرار: يُظهر التكلفة والمكسب الحقيقيَين لكل خيار من اختيار المادة إلى الحزمة الديناميكية الهوائية على الميزان نفسه. بالنسبة للأساطيل ذات الأهداف الكربونية، أصبح اختيار المقطورة يبدأ الآن بقراءة هذا الميزان.</p>
            ',
        ],

        'recycled-steel-trailers' => [
