        'low-emission-coatings' => [
            'title'   => 'الطلاءات المائية والطلاء المسحوق: خفض الانبعاث في التصنيع',
            'excerpt' => 'ورشة الطلاء واحدة من أكثر نقاط الانبعاث كثافة في مصنع المقطورات؛ والأنظمة المائية والطلاء المسحوق يُغيّران هذه الصورة بشكل دائم.',
            'content' => '
